package android.util;
public final class Log {public static final java.util.List<String> lines=new java.util.ArrayList<String>();public static Object forbiddenRing;public static Object forbiddenStats;public static boolean fail;public static int i(String tag,String message){if(forbiddenRing!=null&&Thread.holdsLock(forbiddenRing))throw new AssertionError("logging under ring monitor");if(forbiddenStats!=null&&Thread.holdsLock(forbiddenStats))throw new AssertionError("logging under stats monitor");if(fail)throw new IllegalStateException("log unavailable");lines.add(tag+" "+message);return 0;}}
